@action(detail=True, methods=['patch'], url_path='toggle_status')
def toggle_status(self, request, pk=None):
    """Cycle through pending → in_progress → done → pending."""
    todo = self.get_object()
    cycle = {
        'pending':     'in_progress',
        'in_progress': 'done',
        'done':        'pending',
    }
    todo.status = cycle[todo.status]
    todo.save()
    self._invalidate_cache()
    return Response(TodoStatusSerializer(todo).data)

def validate(self, attrs):
    # If result is selected/rejected, status should be completed
    result = attrs.get('result', None)
    status = attrs.get('status', None)
    if result in ['selected', 'rejected'] and status != 'completed':
        raise serializers.ValidationError({
            "status": "Status must be 'completed' when result is selected or rejected."
        })
    return attrs

